import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
roi = ee.Geometry.Rectangle([-180, 0, 180, 90], geodesic=False)
scale_m = 30000
max_pix = 1e9

def get_year_collection(year, roi):
    ids = ['COPERNICUS/S5P/OFFL/L3_NO2', 'COPERNICUS/S5P/NRTI/L3_NO2']
    start = f"{year}-01-01"
    end = f"{year}-12-31"
    for cid in ids:
        col = (ee.ImageCollection(cid)
               .filterDate(start, end)
               .filterBounds(roi))
        try:
            n = col.size().getInfo()
        except Exception:
            n = 0
        if n and n > 0:
            return cid, col, n
    return None, None, 0

def mask_quality(img):
    # If qa_value exists, mask qa_value > 0.75
    hasQA = img.bandNames().contains('qa_value')
    return ee.Image(ee.Algorithms.If(hasQA, img.updateMask(img.select('qa_value').gt(0.75)), img))

def pick_no2_band(img):
    # Prefer tropospheric_NO2; fallback to NO2_column_number_density
    try:
        bnames = img.bandNames().getInfo() or []
    except Exception:
        bnames = []
    if 'tropospheric_NO2_column_number_density' in bnames:
        return 'tropospheric_NO2_column_number_density'
    if 'NO2_column_number_density' in bnames:
        return 'NO2_column_number_density'
    return None

def compute_year_stats(year):
    cid, col, nimg = get_year_collection(year, roi)
    if nimg == 0 or col is None:
        return {'year': year, 'code': 'C1', 'msg': f'{year} Images: 0'}
    first = col.first()
    band = pick_no2_band(first)
    if band is None:
        return {'year': year, 'code': 'D', 'msg': f'{year} Error: NO2 band not found'}
    colm = col.map(mask_quality).select([band])
    comp = colm.mean()
    # Valid pixel count
    count_dict = comp.reduceRegion(reducer=ee.Reducer.count(), geometry=roi, scale=scale_m, maxPixels=max_pix)
    valid_count = count_dict.get(band).getInfo()
    if valid_count is None or int(valid_count) == 0:
        return {'year': year, 'code': 'C2', 'msg': f'{year} ValidPx: 0'}
    # Total pixel count baseline (sampling grid)
    total_count = ee.Image.constant(1).rename('const').reduceRegion(
        reducer=ee.Reducer.sum(), geometry=roi, scale=scale_m, maxPixels=max_pix
    ).get('const').getInfo()
    # Area-weighted mean
    area = ee.Image.pixelArea()
    weighted_sum = comp.multiply(area).reduceRegion(
        reducer=ee.Reducer.sum(), geometry=roi, scale=scale_m, maxPixels=max_pix
    ).get(band).getInfo()
    area_sum = area.updateMask(comp.mask()).reduceRegion(
        reducer=ee.Reducer.sum(), geometry=roi, scale=scale_m, maxPixels=max_pix
    ).get('area').getInfo()
    try:
        mean_val = None if (weighted_sum is None or area_sum in (None, 0)) else (weighted_sum / area_sum)
    except Exception:
        mean_val = None
    # Validate mean
    if (mean_val is None) or (isinstance(mean_val, float) and (math.isnan(mean_val) or abs(mean_val) > 0.1)):
        return {'year': year, 'code': 'C3', 'msg': f'{year} Mean invalid'}
    valid_pct = 100.0 * float(valid_count) / float(total_count) if total_count else 0.0
    return {
        'year': year, 'code': 'OK', 'dataset': cid, 'images': int(nimg),
        'valid_px': int(valid_count), 'total_px': int(total_count),
        'valid_pct': valid_pct, 'mean': float(mean_val), 'band': band
    }

try:
    s2019 = compute_year_stats(2019)
    if s2019['code'] != 'OK':
        print(s2019.get('msg', '2019 error'))
        print("C1" if s2019['code']=='C1' else ("C2" if s2019['code']=='C2' else ("C3" if s2019['code']=='C3' else "D")))
        sys.exit(0)
    s2020 = compute_year_stats(2020)
    if s2020['code'] != 'OK':
        print(s2020.get('msg', '2020 error'))
        print("C1" if s2020['code']=='C1' else ("C2" if s2020['code']=='C2' else ("C3" if s2020['code']=='C3' else "D")))
        sys.exit(0)

    # Evidence prints (<=20 lines total)
    print(f"2019 Images: {s2019['images']}, Mean NO2 ({s2019['band']}): {s2019['mean']:.2e} mol/m^2, "
          f"ValidPx: {s2019['valid_px']}/{s2019['total_px']} ({s2019['valid_pct']:.1f}%), Dataset: {s2019['dataset']}")
    print(f"2020 Images: {s2020['images']}, Mean NO2 ({s2020['band']}): {s2020['mean']:.2e} mol/m^2, "
          f"ValidPx: {s2020['valid_px']}/{s2020['total_px']} ({s2020['valid_pct']:.1f}%), Dataset: {s2020['dataset']}")
    delta = s2020['mean'] - s2019['mean']
    rel = (delta / s2019['mean'] * 100.0) if s2019['mean'] != 0 else float('nan')
    print(f"Change 2020-2019: {delta:.2e} mol/m^2 ({rel:.2f}%)")

    # Final decision
    if math.isnan(rel):
        print("C3")
    elif delta > 0:
        print("A")
    else:
        print("B")

except Exception as e:
    print(f"Error: {str(e)[:120]}")
    print("D")
